sp_widget.css:
.kpi-dashboard {
  padding: 15px 0;
}

.kpi-card {
  border-radius: 6px;
  padding: 20px 15px;
  text-align: center;
  margin-bottom: 15px;
  color: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  transition: transform 0.2s ease;
}

.kpi-card:hover {
  transform: translateY(-3px);
}

.kpi-icon {
  font-size: 28px;
  margin-bottom: 8px;
  opacity: 0.9;
}

.kpi-count {
  font-size: 32px;
  font-weight: 700;
  line-height: 1.2;
}

.kpi-label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-top: 5px;
  opacity: 0.9;
}

.kpi-total {
  background-color: $brand-primary;
}

.kpi-open {
  background-color: #E67E22;
}

.kpi-progress {
  background-color: #3498DB;
}

.kpi-resolved {
  background-color: #27AE60;
}

.kpi-critical {
  background-color: #C0392B;
}

sp_widget.script:
(function() {
    data.kpis = [];
    data.userRole = 'none';

    // Determine user role
    if (gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin')) {
        data.userRole = 'supervisor';
    } else if (gs.hasRole('x_1956908_wareho_0.technician')) {
        data.userRole = 'technician';
    } else if (gs.hasRole('x_1956908_wareho_0.staff')) {
        data.userRole = 'staff';
    }

    var userId = gs.getUserID();
    var tableName = 'x_1956908_wareho_0_exception';

    function getCount(additionalQuery) {
        var ga = new GlideAggregate(tableName);
        // Role-based base filter
        if (data.userRole === 'staff') {
            ga.addQuery('reported_by', userId);
        } else if (data.userRole === 'technician') {
            ga.addQuery('assigned_to', userId);
        }
        // Additional filter
        if (additionalQuery) {
            ga.addEncodedQuery(additionalQuery);
        }
        ga.addAggregate('COUNT');
        ga.query();
        if (ga.next()) {
            return parseInt(ga.getAggregate('COUNT'), 10);
        }
        return 0;
    }

    var totalCount = getCount('');
    var openCount = getCount('statusINnew,assigned');
    var inProgressCount = getCount('status=in_progress');
    var resolvedCount = getCount('statusINresolved,closed');
    var criticalCount = getCount('severity=critical^statusNOT INresolved,closed');

    data.kpis = [
        { label: 'Total Exceptions', count: totalCount, icon: 'fa-database', bgClass: 'kpi-total' },
        { label: 'Open', count: openCount, icon: 'fa-folder-open', bgClass: 'kpi-open' },
        { label: 'In Progress', count: inProgressCount, icon: 'fa-cogs', bgClass: 'kpi-progress' },
        { label: 'Resolved', count: resolvedCount, icon: 'fa-check-circle', bgClass: 'kpi-resolved' },
        { label: 'Critical', count: criticalCount, icon: 'fa-exclamation-triangle', bgClass: 'kpi-critical' }
    ];
})();
